package com.flowdesk.alert.recovery;
import com.flowdesk.common.tenant.ActorRef;import com.flowdesk.common.tenant.TenantContext;import java.io.ByteArrayOutputStream;import java.nio.ByteBuffer;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.Arrays;import java.util.HexFormat;import java.util.UUID;
final class AlertRecoveryIdempotency{private AlertRecoveryIdempotency(){}static UUID auditId(TenantContext c,UUID recovery,String key){if(!(c.actor() instanceof ActorRef.Human h))throw new IllegalStateException();return uuid(digest("FD-IDEMPOTENCY-V1",c.tenantId(),"USER",h.userId(),"API-060","ALERT",recovery,key));}static String requestDigest(UUID r,String reason){return HexFormat.of().formatHex(digest("FD-ALERT-RECOVERY-INTENT-V1",r,reason));}static UUID outcomeAuditId(UUID t,UUID c,String outcome){return uuid(digest("FD-ALERT-RECOVERY-OUTCOME-V1",t,c,outcome));}private static byte[] digest(Object...fs){try{var out=new ByteArrayOutputStream();for(Object f:fs){byte[] b=f instanceof UUID id?ByteBuffer.allocate(16).putLong(id.getMostSignificantBits()).putLong(id.getLeastSignificantBits()).array():f.toString().getBytes(StandardCharsets.UTF_8);out.writeBytes(ByteBuffer.allocate(4).putInt(b.length).array());out.writeBytes(b);}return MessageDigest.getInstance("SHA-256").digest(out.toByteArray());}catch(Exception e){throw new IllegalStateException(e);}}private static UUID uuid(byte[] d){var b=ByteBuffer.wrap(Arrays.copyOf(d,16));return new UUID(b.getLong(),b.getLong());}}
